function reverse(s) {
  const stack = [];
  for (const ch of s) stack.push(ch);         // H, e, l, l, o go in...
  let out = "";
  while (stack.length > 0) out += stack.pop();   // ...o, l, l, e, H come out
  return out;
}

def reverse(s):
    stack = []
    for ch in s:
        stack.append(ch)          # H, e, l, l, o go in...
    out = []
    while stack:
        out.append(stack.pop())   # ...o, l, l, e, H come out
    return "".join(out)

String reverse(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char ch : s.toCharArray()) stack.push(ch);    // H, e, l, l, o go in...
    StringBuilder out = new StringBuilder();
    while (!stack.isEmpty()) out.append(stack.pop());  // ...o, l, l, e, H come out
    return out.toString();
}

string reverse(const string& s) {
    stack<char> st;
    for (char ch : s) st.push(ch);       // H, e, l, l, o go in...
    string out;
    while (!st.empty()) {
        out += st.top();                 // ...o, l, l, e, H come out
        st.pop();
    }
    return out;
}
